import Foundation

// MARK: - Modes

/// Input modes. Key bindings are looked up per mode.
public enum Mode: String, CaseIterable, Sendable {
    /// Vim-style navigation. The default.
    case normal
    /// The `:` / `/` / `?` input bar has focus. Keys go to the text field.
    case command
    /// A form field, text annotation or other text input has focus.
    /// Only `<Esc>` is intercepted; everything else is typed normally.
    case insert
    /// Fullscreen one-page-at-a-time presentation.
    case presentation
}

// MARK: - Actions

/// Every user-triggerable operation. The raw value is the name used in the rc
/// file (`map j scroll-down`) and is also what `:` commands resolve to.
public enum ActionName: String, CaseIterable, Sendable {
    // Scrolling and navigation (count = repeat)
    case scrollDown = "scroll-down"
    case scrollUp = "scroll-up"
    case scrollLeft = "scroll-left"
    case scrollRight = "scroll-right"
    case scrollHalfDown = "scroll-half-down"
    case scrollHalfUp = "scroll-half-up"
    case scrollPageDown = "scroll-page-down"
    case scrollPageUp = "scroll-page-up"
    case pageNext = "page-next"
    case pagePrevious = "page-previous"
    /// No count: first page. With count N: page N.
    case gotoFirst = "goto-first"
    /// No count: last page. With count N: page N.
    case gotoLast = "goto-last"
    /// Argument or count is a 1-based page number.
    case gotoPage = "goto-page"

    // Zoom and layout
    case zoomIn = "zoom-in"
    case zoomOut = "zoom-out"
    /// 100%.
    case zoomReset = "zoom-reset"
    /// Argument is a percentage, e.g. "150".
    case zoomSet = "zoom-set"
    case fitPage = "fit-page"
    case fitWidth = "fit-width"
    case rotateCW = "rotate-cw"
    case rotateCCW = "rotate-ccw"
    case toggleDualPage = "toggle-dual-page"
    case toggleContinuous = "toggle-continuous"
    case toggleRecolor = "toggle-recolor"
    case toggleTrim = "toggle-trim"

    // Search
    /// Opens the input bar with `/`.
    case searchForward = "search-forward"
    /// Opens the input bar with `?`.
    case searchBackward = "search-backward"
    /// Argument is the query. Issued by the input bar, also while typing when
    /// incremental search is on.
    case searchRun = "search-run"
    case searchNext = "search-next"
    case searchPrevious = "search-previous"
    case searchClear = "search-clear"

    // Marks and jump list
    /// Awaits one character (the mark name), delivered as the argument.
    case markSet = "mark-set"
    /// Awaits one character (the mark name), delivered as the argument.
    case markJump = "mark-jump"
    case jumpBack = "jump-back"
    case jumpForward = "jump-forward"

    // Window chrome
    case toggleSidebar = "toggle-sidebar"
    case toggleToolbar = "toggle-toolbar"
    case toggleStatusbar = "toggle-statusbar"
    case toggleFullscreen = "toggle-fullscreen"
    case togglePresentation = "toggle-presentation"
    case toggleInspector = "toggle-inspector"

    // Input bar and config
    /// Opens the input bar with `:`. Optional argument pre-fills the text.
    case enterCommand = "enter-command"
    /// `<Esc>` in normal mode: cancel pending keys, active tool, selection,
    /// search highlight.
    case abort = "abort"
    /// Argument: "<option> <value>".
    case setOption = "set"
    /// Argument: "[mode] <keys> <action> [arg]".
    case mapKey = "map"
    /// Argument: "[mode] <keys>".
    case unmapKey = "unmap"
    /// Argument: theme name.
    case setTheme = "theme"
    /// Argument: path of an rc file. No argument: reload the user rc.
    case sourceConfig = "source"

    // Files
    /// Argument: path. No argument: show the Open panel.
    case open = "open"
    case openPalette = "open-palette"
    case reload = "reload"
    case close = "close"
    case quit = "quit"
    case save = "save"
    /// Argument: path. No argument: show the Save panel.
    case saveAs = "save-as"
    /// Argument: optional format/path. Shows the export sheet.
    case export = "export"
    case print = "print"

    // Editing
    case undo = "undo"
    case redo = "redo"
    case copy = "copy"
    case selectAll = "select-all"

    // Markup (PDF)
    /// Apply to the current text selection.
    case annotateHighlight = "annotate-highlight"
    case annotateUnderline = "annotate-underline"
    case annotateStrikethrough = "annotate-strikethrough"
    /// Tools: the next mouse drag/click creates the annotation.
    case toolSelect = "tool-select"
    case toolNote = "tool-note"
    case toolText = "tool-text"
    case toolRectangle = "tool-rectangle"
    case toolOval = "tool-oval"
    case toolLine = "tool-line"
    case toolArrow = "tool-arrow"
    case toolInk = "tool-ink"
    case annotationDelete = "annotation-delete"

    // Forms and signatures
    case signaturePlace = "signature-place"
    case signatureManage = "signature-manage"

    // Page management (PDF). Operate on the sidebar selection, else the
    // current page.
    case pageDelete = "page-delete"
    case pageRotateCW = "page-rotate-cw"
    case pageRotateCCW = "page-rotate-ccw"
    /// Argument: path of a PDF/image to insert after the current page. No
    /// argument: show the Open panel.
    case pageInsert = "page-insert"
    case pageInsertBlank = "page-insert-blank"
    /// Argument: "<from>-<to> [path]".
    case pageExport = "page-export"

    // Image editing
    case imageCrop = "image-crop"
    /// Argument: "<width>x<height>" in pixels. No argument: show the sheet.
    case imageResize = "image-resize"
    case imageAdjust = "image-adjust"
    case imageFlipHorizontal = "image-flip-horizontal"
    case imageFlipVertical = "image-flip-vertical"

    // Extras
    case ocr = "ocr"

    /// Actions that consume the next typed character as their argument.
    public var awaitsCharacter: Bool {
        self == .markSet || self == .markJump
    }
}

public struct Action: Hashable, Sendable {
    public var name: ActionName
    public var argument: String?

    public init(_ name: ActionName, _ argument: String? = nil) {
        self.name = name
        self.argument = argument
    }
}

/// An action plus the vim count typed before it (`5j`), if any.
public struct ActionInvocation: Hashable, Sendable {
    public var action: Action
    public var count: Int?

    public init(_ action: Action, count: Int? = nil) {
        self.action = action
        self.count = count
    }

    public init(_ name: ActionName, _ argument: String? = nil, count: Int? = nil) {
        self.init(Action(name, argument), count: count)
    }
}

// MARK: - Key bindings

/// One `map` line. `keys` is in vim notation: `j`, `gg`, `<C-d>`, `<Space>o`,
/// `<S-Tab>`, `<F5>`, `<Esc>`, `<lt>`.
public struct KeyBinding: Hashable, Sendable {
    public var mode: Mode
    public var keys: String
    public var action: Action

    public init(mode: Mode = .normal, keys: String, action: Action) {
        self.mode = mode
        self.keys = keys
        self.action = action
    }
}

// MARK: - Colors

public struct RGBA: Hashable, Sendable {
    public var r: Double
    public var g: Double
    public var b: Double
    public var a: Double

    public init(r: Double, g: Double, b: Double, a: Double = 1) {
        self.r = r
        self.g = g
        self.b = b
        self.a = a
    }

    /// Accepts `#rgb`, `#rrggbb`, `#rrggbbaa` (the `#` is optional).
    public init?(hex: String) {
        var s = Substring(hex.trimmingCharacters(in: .whitespaces))
        if s.hasPrefix("#") { s = s.dropFirst() }
        if s.count == 3 { s = Substring(s.map { "\($0)\($0)" }.joined()) }
        guard s.count == 6 || s.count == 8, let v = UInt64(s, radix: 16) else { return nil }
        if s.count == 6 {
            self.init(r: Double((v >> 16) & 0xff) / 255, g: Double((v >> 8) & 0xff) / 255,
                      b: Double(v & 0xff) / 255)
        } else {
            self.init(r: Double((v >> 24) & 0xff) / 255, g: Double((v >> 16) & 0xff) / 255,
                      b: Double((v >> 8) & 0xff) / 255, a: Double(v & 0xff) / 255)
        }
    }

    public init(_ hex: StaticString) {
        self.init(hex: "\(hex)")!
    }

    /// Relative luminance, 0 (black) to 1 (white).
    public var luminance: Double { 0.2126 * r + 0.7152 * g + 0.0722 * b }
}

// MARK: - Theme

/// Colors for the UI and for page recoloring. Field names map 1:1 to rc keys
/// via `Theme.colorKeys` (`set statusbar-bg #1e1e2e`).
public struct Theme: Hashable, Sendable {
    public var name: String
    /// Drives the window appearance (dark/light title bar, scrollers, sheets).
    public var isDark: Bool

    /// Window background, visible around and between pages.
    public var defaultBg: RGBA
    public var defaultFg: RGBA
    public var statusbarBg: RGBA
    public var statusbarFg: RGBA
    public var inputbarBg: RGBA
    public var inputbarFg: RGBA
    public var notificationBg: RGBA
    public var notificationFg: RGBA
    public var notificationErrorBg: RGBA
    public var notificationErrorFg: RGBA
    /// Fuzzy opener / completion list.
    public var completionBg: RGBA
    public var completionFg: RGBA
    public var completionHighlightBg: RGBA
    public var completionHighlightFg: RGBA
    public var sidebarBg: RGBA
    public var sidebarFg: RGBA
    /// Search matches.
    public var highlightColor: RGBA
    /// The current search match.
    public var highlightActiveColor: RGBA
    /// Selection, focus rings, current page marker.
    public var accent: RGBA
    /// Recolor: what white (paper) becomes.
    public var recolorLightColor: RGBA
    /// Recolor: what black (ink) becomes.
    public var recolorDarkColor: RGBA

    public init(
        name: String, isDark: Bool,
        defaultBg: RGBA, defaultFg: RGBA,
        statusbarBg: RGBA, statusbarFg: RGBA,
        inputbarBg: RGBA, inputbarFg: RGBA,
        notificationBg: RGBA, notificationFg: RGBA,
        notificationErrorBg: RGBA, notificationErrorFg: RGBA,
        completionBg: RGBA, completionFg: RGBA,
        completionHighlightBg: RGBA, completionHighlightFg: RGBA,
        sidebarBg: RGBA, sidebarFg: RGBA,
        highlightColor: RGBA, highlightActiveColor: RGBA,
        accent: RGBA,
        recolorLightColor: RGBA, recolorDarkColor: RGBA
    ) {
        self.name = name
        self.isDark = isDark
        self.defaultBg = defaultBg
        self.defaultFg = defaultFg
        self.statusbarBg = statusbarBg
        self.statusbarFg = statusbarFg
        self.inputbarBg = inputbarBg
        self.inputbarFg = inputbarFg
        self.notificationBg = notificationBg
        self.notificationFg = notificationFg
        self.notificationErrorBg = notificationErrorBg
        self.notificationErrorFg = notificationErrorFg
        self.completionBg = completionBg
        self.completionFg = completionFg
        self.completionHighlightBg = completionHighlightBg
        self.completionHighlightFg = completionHighlightFg
        self.sidebarBg = sidebarBg
        self.sidebarFg = sidebarFg
        self.highlightColor = highlightColor
        self.highlightActiveColor = highlightActiveColor
        self.accent = accent
        self.recolorLightColor = recolorLightColor
        self.recolorDarkColor = recolorDarkColor
    }

    /// Builds a full theme from a small palette. Presets use this.
    public init(
        name: String, isDark: Bool,
        base: RGBA, surface: RGBA, overlay: RGBA, text: RGBA, subtext: RGBA,
        accent: RGBA, yellow: RGBA, orange: RGBA, red: RGBA
    ) {
        self.init(
            name: name, isDark: isDark,
            defaultBg: surface, defaultFg: text,
            statusbarBg: surface, statusbarFg: subtext,
            inputbarBg: base, inputbarFg: text,
            notificationBg: base, notificationFg: text,
            notificationErrorBg: base, notificationErrorFg: red,
            completionBg: base, completionFg: text,
            completionHighlightBg: overlay, completionHighlightFg: accent,
            sidebarBg: surface, sidebarFg: subtext,
            highlightColor: RGBA(r: yellow.r, g: yellow.g, b: yellow.b, a: 0.45),
            highlightActiveColor: RGBA(r: orange.r, g: orange.g, b: orange.b, a: 0.6),
            accent: accent,
            recolorLightColor: base, recolorDarkColor: text
        )
    }

    /// rc key -> field. The single source of truth for theme color option names.
    public static let colorKeys: [String: WritableKeyPath<Theme, RGBA>] = [
        "default-bg": \.defaultBg,
        "default-fg": \.defaultFg,
        "statusbar-bg": \.statusbarBg,
        "statusbar-fg": \.statusbarFg,
        "inputbar-bg": \.inputbarBg,
        "inputbar-fg": \.inputbarFg,
        "notification-bg": \.notificationBg,
        "notification-fg": \.notificationFg,
        "notification-error-bg": \.notificationErrorBg,
        "notification-error-fg": \.notificationErrorFg,
        "completion-bg": \.completionBg,
        "completion-fg": \.completionFg,
        "completion-highlight-bg": \.completionHighlightBg,
        "completion-highlight-fg": \.completionHighlightFg,
        "sidebar-bg": \.sidebarBg,
        "sidebar-fg": \.sidebarFg,
        "highlight-color": \.highlightColor,
        "highlight-active-color": \.highlightActiveColor,
        "accent": \.accent,
        "recolor-lightcolor": \.recolorLightColor,
        "recolor-darkcolor": \.recolorDarkColor,
    ]

    /// Neutral fallbacks used before any config is loaded.
    public static let fallbackDark = Theme(
        name: "default-dark", isDark: true,
        base: RGBA("#1c1c1e"), surface: RGBA("#141416"), overlay: RGBA("#2c2c2e"),
        text: RGBA("#e5e5ea"), subtext: RGBA("#aeaeb2"),
        accent: RGBA("#0a84ff"), yellow: RGBA("#ffd60a"), orange: RGBA("#ff9f0a"),
        red: RGBA("#ff453a"))

    public static let fallbackLight = Theme(
        name: "default-light", isDark: false,
        base: RGBA("#ffffff"), surface: RGBA("#ececec"), overlay: RGBA("#d9d9de"),
        text: RGBA("#1c1c1e"), subtext: RGBA("#48484a"),
        accent: RGBA("#007aff"), yellow: RGBA("#ffcc00"), orange: RGBA("#ff9500"),
        red: RGBA("#ff3b30"))
}

// MARK: - Options

public enum FitMode: String, CaseIterable, Sendable {
    case width, page, none
}

/// Typed option store. rc names are listed in `DefaultConfig.rc`; the mapping
/// from rc name to field lives in `Config/` (owned by the config agent).
public struct Options: Hashable, Sendable {
    // Scrolling
    /// Points per `j`/`k` at 100% zoom-independent screen space.
    public var scrollStep: Double = 80
    public var scrollHStep: Double = 80
    public var smoothScroll: Bool = true
    /// Seconds for a keyboard scroll animation to settle.
    public var scrollDuration: Double = 0.16
    /// Fraction of the viewport kept when paging with scroll-page-*.
    public var scrollPageOverlap: Double = 0.1

    // Zoom and layout
    /// Multiplicative step, e.g. 1.1 = 10% per press.
    public var zoomStep: Double = 1.1
    public var zoomMin: Double = 0.1
    public var zoomMax: Double = 10
    public var defaultFit: FitMode = .width
    public var continuous: Bool = true
    public var dualPage: Bool = false
    /// In dual-page mode, show the first page alone (book layout).
    public var dualPageBook: Bool = true
    /// Gap between pages in points.
    public var pagePadding: Double = 8

    // Recolor and trim
    public var recolor: Bool = false
    /// Keep the hue of colored content; only remap lightness.
    public var recolorKeepHue: Bool = false
    public var trimMargins: Bool = false
    /// Points of margin kept around detected content.
    public var trimPadding: Double = 6

    // Themes
    /// A theme name, or "auto" to follow the system using themeLight/themeDark.
    public var theme: String = "auto"
    public var themeLight: String = "catppuccin-latte"
    public var themeDark: String = "catppuccin-mocha"

    // Chrome
    public var statusbar: Bool = true
    public var toolbar: Bool = false
    public var sidebar: Bool = false
    public var sidebarWidth: Double = 180
    /// UI font for the status bar, input bar and palette. Empty = system mono.
    public var font: String = ""
    public var fontSize: Double = 12

    // Keys and search
    /// Milliseconds to wait when a key sequence is ambiguous (`g` vs `gg`).
    public var keyTimeout: Int = 700
    public var incrementalSearch: Bool = true
    public var searchWrap: Bool = true
    /// Case-insensitive unless the query contains an uppercase letter.
    public var searchSmartCase: Bool = true

    // Files
    public var autoReload: Bool = true
    public var synctex: Bool = true
    /// Run on Cmd-click. `%{input}` = source file, `%{line}` = line,
    /// `%{column}` = column.
    public var synctexEditorCommand: String = ""
    /// BCP-47 codes, comma separated. Empty = automatic.
    public var ocrLanguages: String = ""
    /// PDFKit's own automatic page analysis (form/table detection and OCR
    /// of every visible page). Off: much less CPU and memory while scrolling.
    public var pdfkitAnalysis: Bool = false

    public init() {}
}

// MARK: - Config

public struct ConfigDiagnostic: Hashable, Sendable {
    public var file: String
    public var line: Int
    public var message: String

    public init(file: String, line: Int, message: String) {
        self.file = file
        self.line = line
        self.message = message
    }
}

/// The fully resolved configuration: defaults, then the user's rc on top.
public struct Config: Sendable {
    public var options: Options
    /// In definition order; later bindings for the same (mode, keys) win and
    /// `unmap` has already been applied.
    public var bindings: [KeyBinding]
    /// `set <color-key> <hex>` overrides applied on top of whichever theme is
    /// active.
    public var themeOverrides: [String: RGBA]
    /// User-defined themes from the rc (`theme-define`), by name.
    public var customThemes: [String: Theme]
    public var diagnostics: [ConfigDiagnostic]

    public init(
        options: Options = Options(), bindings: [KeyBinding] = [],
        themeOverrides: [String: RGBA] = [:], customThemes: [String: Theme] = [:],
        diagnostics: [ConfigDiagnostic] = []
    ) {
        self.options = options
        self.bindings = bindings
        self.themeOverrides = themeOverrides
        self.customThemes = customThemes
        self.diagnostics = diagnostics
    }
}

// MARK: - Positions

/// A place in a document, used by marks and the jump list.
public struct DocumentPosition: Hashable, Sendable {
    /// 0-based page index.
    public var page: Int
    /// Offset of the viewport's top-left corner within the page, as a fraction
    /// of the page's width/height (0...1, origin top-left).
    public var x: Double
    public var y: Double
    /// Zoom to restore, if the mark should restore it.
    public var zoom: Double?

    public init(page: Int, x: Double = 0, y: Double = 0, zoom: Double? = nil) {
        self.page = page
        self.x = x
        self.y = y
        self.zoom = zoom
    }
}
